		/// </summary>
		/// <param name="activeView">Currently active view</param>
		/// <param name="filter">filter string used to filter the toolbox items</param>
		protected virtual bool SelectedToolboxItemSupportsFilterString(DslDiagrams::DiagramView activeView, string filter)
		{
			return activeView.SelectedToolboxItemSupportsFilterString(filter);
		}
		/// <summary>
		/// Override to provide the right mouse action when trying
		/// to create links on the diagram
		/// </summary>
		/// <param name="pointArgs"></param>
		public override void OnViewMouseEnter(DslDiagrams::DiagramPointEventArgs pointArgs)
		{
			if (pointArgs  == null) throw new global::System.ArgumentNullException("pointArgs");
		
			DslDiagrams::DiagramView activeView = this.ActiveDiagramView;
			if(activeView != null)
			{
				DslDiagrams::MouseAction action = null;
				if (SelectedToolboxItemSupportsFilterString(activeView, global::Linx.BusinessDataModelDesigner.BusinessDataModelDesignerToolboxHelper.AssociationFilterString))
				{
					if (this.associationConnectAction == null)
					{
						this.associationConnectAction = new global::Linx.BusinessDataModelDesigner.AssociationConnectAction(this);
						this.associationConnectAction.MouseActionDeactivated += new DslDiagrams::MouseAction.MouseActionDeactivatedEventHandler(OnConnectActionDeactivated);
					}
					action = this.associationConnectAction;
				} 
				else if (SelectedToolboxItemSupportsFilterString(activeView, global::Linx.BusinessDataModelDesigner.BusinessDataModelDesignerToolboxHelper.GeneralizationFilterString))
				{
					if (this.generalizationConnectAction == null)
					{
						this.generalizationConnectAction = new global::Linx.BusinessDataModelDesigner.GeneralizationConnectAction(this);
						this.generalizationConnectAction.MouseActionDeactivated += new DslDiagrams::MouseAction.MouseActionDeactivatedEventHandler(OnConnectActionDeactivated);
					}
					action = this.generalizationConnectAction;
				} 
				else if (SelectedToolboxItemSupportsFilterString(activeView, global::Linx.BusinessDataModelDesigner.BusinessDataModelDesignerToolboxHelper.MultipleAssociationOriginFilterString))
				{
					if (this.multipleAssociationOriginConnectAction == null)
					{
						this.multipleAssociationOriginConnectAction = new global::Linx.BusinessDataModelDesigner.MultipleAssociationOriginConnectAction(this);
						this.multipleAssociationOriginConnectAction.MouseActionDeactivated += new DslDiagrams::MouseAction.MouseActionDeactivatedEventHandler(OnConnectActionDeactivated);
					}
					action = this.multipleAssociationOriginConnectAction;
				} 
				else if (SelectedToolboxItemSupportsFilterString(activeView, global::Linx.BusinessDataModelDesigner.BusinessDataModelDesignerToolboxHelper.MultipleAssociationTargetFilterString))
				{
					if (this.multipleAssociationTargetConnectAction == null)
					{
						this.multipleAssociationTargetConnectAction = new global::Linx.BusinessDataModelDesigner.MultipleAssociationTargetConnectAction(this);
						this.multipleAssociationTargetConnectAction.MouseActionDeactivated += new DslDiagrams::MouseAction.MouseActionDeactivatedEventHandler(OnConnectActionDeactivated);
					}
					action = this.multipleAssociationTargetConnectAction;
				} 
				else if (SelectedToolboxItemSupportsFilterString(activeView, global::Linx.BusinessDataModelDesigner.BusinessDataModelDesignerToolboxHelper.CommentsReferenceTypesFilterString))
				{
					if (this.commentsReferenceTypesConnectAction == null)
					{
						this.commentsReferenceTypesConnectAction = new global::Linx.BusinessDataModelDesigner.CommentsReferenceTypesConnectAction(this);
						this.commentsReferenceTypesConnectAction.MouseActionDeactivated += new DslDiagrams::MouseAction.MouseActionDeactivatedEventHandler(OnConnectActionDeactivated);
					}
					action = this.commentsReferenceTypesConnectAction;
				} 
				else if (SelectedToolboxItemSupportsFilterString(activeView, global::Linx.BusinessDataModelDesigner.BusinessDataModelDesignerToolboxHelper.GeneralizationSharedFilterString))
				{
					if (this.generalizationSharedConnectAction == null)
					{
						this.generalizationSharedConnectAction = new global::Linx.BusinessDataModelDesigner.GeneralizationSharedConnectAction(this);
						this.generalizationSharedConnectAction.MouseActionDeactivated += new DslDiagrams::MouseAction.MouseActionDeactivatedEventHandler(OnConnectActionDeactivated);
					}
					action = this.generalizationSharedConnectAction;
				} 
				else if (SelectedToolboxItemSupportsFilterString(activeView, global::Linx.BusinessDataModelDesigner.BusinessDataModelDesignerToolboxHelper.AssociationImplementationToolFilterString))
				{
					if (this.associationImplementationToolConnectAction == null)
					{
						this.associationImplementationToolConnectAction = new global::Linx.BusinessDataModelDesigner.AssociationImplementationToolConnectAction(this);
						this.associationImplementationToolConnectAction.MouseActionDeactivated += new DslDiagrams::MouseAction.MouseActionDeactivatedEventHandler(OnConnectActionDeactivated);
					}
					action = this.associationImplementationToolConnectAction;
				} 
				else if (SelectedToolboxItemSupportsFilterString(activeView, global::Linx.BusinessDataModelDesigner.BusinessDataModelDesignerToolboxHelper.ModelViewAssociationToolFilterString))
				{
					if (this.modelViewAssociationToolConnectAction == null)
					{
						this.modelViewAssociationToolConnectAction = new global::Linx.BusinessDataModelDesigner.ModelViewAssociationToolConnectAction(this);
						this.modelViewAssociationToolConnectAction.MouseActionDeactivated += new DslDiagrams::MouseAction.MouseActionDeactivatedEventHandler(OnConnectActionDeactivated);
					}
					action = this.modelViewAssociationToolConnectAction;
				} 
				else
				{
					action = null;
				}
				
				if (pointArgs.DiagramClientView.ActiveMouseAction != action)
				{
					try
					{
						this.changingMouseAction = true;
						pointArgs.DiagramClientView.ActiveMouseAction = action;
					}
					finally
					{
						this.changingMouseAction = false;
					}
				}
			}
		}
		
		/// <summary>
		/// Snap toolbox selection back to regular pointer after using a custom connect action.
		/// </summary>
		private void OnConnectActionDeactivated(object sender, DslDiagrams::DiagramEventArgs e)
		{
			OnMouseActionDeactivated();
		}
		
		/// <summary>
		/// Overridable method to manage the mouse deactivation. The default implementation snap stoolbox selection back to regular pointer 
		/// after using a custom connect action.
		/// </summary>
		protected virtual void OnMouseActionDeactivated()
		{
			DslDiagrams::DiagramView activeView = this.ActiveDiagramView;
		
			if (activeView != null && activeView.Toolbox != null)
			{
				// If we're not changing mouse action due to changing toolbox selection change,
				// reset toolbox selection.
				if (!this.changingMouseAction)
				{
					activeView.Toolbox.SelectedToolboxItemUsed();
				}
			}
		}
