		/// <summary>
		/// Dispose of connect actions.
		/// </summary>
		protected override void Dispose(bool disposing)
		{
			try
			{
				if(disposing)
				{
					if(this.associationConnectAction != null)
					{
						this.associationConnectAction.Dispose();
						this.associationConnectAction = null;
					}
					if(this.generalizationConnectAction != null)
					{
						this.generalizationConnectAction.Dispose();
						this.generalizationConnectAction = null;
					}
					if(this.multipleAssociationOriginConnectAction != null)
					{
						this.multipleAssociationOriginConnectAction.Dispose();
						this.multipleAssociationOriginConnectAction = null;
					}
					if(this.multipleAssociationTargetConnectAction != null)
					{
						this.multipleAssociationTargetConnectAction.Dispose();
						this.multipleAssociationTargetConnectAction = null;
					}
					if(this.commentsReferenceTypesConnectAction != null)
					{
						this.commentsReferenceTypesConnectAction.Dispose();
						this.commentsReferenceTypesConnectAction = null;
					}
					if(this.generalizationSharedConnectAction != null)
					{
						this.generalizationSharedConnectAction.Dispose();
						this.generalizationSharedConnectAction = null;
					}
					if(this.associationImplementationToolConnectAction != null)
					{
						this.associationImplementationToolConnectAction.Dispose();
						this.associationImplementationToolConnectAction = null;
					}
					if(this.modelViewAssociationToolConnectAction != null)
					{
						this.modelViewAssociationToolConnectAction.Dispose();
						this.modelViewAssociationToolConnectAction = null;
					}
					this.UnsubscribeCompartmentItemsEvents();
				}
			}
			finally
			{
				base.Dispose(disposing);
			}
		}
